package dev.veltraph.client.navigation;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class SharedMovementCoordinatorTest {
    static final Vec3 GOAL=new Vec3(12,70,0), LANDING=new Vec3(8,70,0);
    static SharedMovementPolicy.Options options(){return new SharedMovementPolicy.Options(Set.of(SharedMovementPolicy.Mode.WALK,SharedMovementPolicy.Mode.RUN,SharedMovementPolicy.Mode.AOTV),SharedMovementPolicy.Purpose.GENERAL_TRAVEL,2,1000,.3,1.25);}
    static SharedMovementCoordinator.Lease lease(){return new SharedMovementCoordinator.Lease(new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),4,9);}
    static SharedMovementPolicy.Candidate c(String id,SharedMovementPolicy.Mode m,Vec3 p,double cost){return new SharedMovementPolicy.Candidate(id,m,p,cost,SharedMovementPolicy.device(m)?1:0,new Object(),new Object(),SharedMovementPolicy.device(m)?new Object():null);}
    static class P implements SharedMovementCoordinator.Port {
        long time=100;boolean valid=true,permit=true,atGoal;int stops,begins,ticks;Runnable candidatesHook=()->{},beginHook=()->{},tickHook=()->{};
        List<SharedMovementPolicy.Candidate> choices=List.of(c("walk",SharedMovementPolicy.Mode.WALK,GOAL,12));
        SharedMovementCoordinator.Lease owner;SharedMovementCoordinator.Issue issue;
        SharedMovementCoordinator.Progress progress=SharedMovementCoordinator.Progress.ACTIVE;
        SharedMovementCoordinator.AppliedReceipt receipt;
        public long now(){return time;}public boolean owned(SharedMovementCoordinator.Lease l){owner=l;return valid;}
        public List<SharedMovementPolicy.Candidate> candidates(Vec3 g,SharedMovementPolicy.Options o,int uses){candidatesHook.run();return choices;}
        public boolean permitted(SharedMovementCoordinator.Lease l,SharedMovementPolicy.Candidate c){return permit;}
        public SharedMovementCoordinator.Issue begin(SharedMovementCoordinator.Lease l,SharedMovementPolicy.Candidate c){begins++;issue=new SharedMovementCoordinator.Issue(new Object(),new Object(),30,time,SharedMovementPolicy.device(c.mode()));beginHook.run();return issue;}
        public SharedMovementCoordinator.Progress tick(SharedMovementCoordinator.Lease l,SharedMovementPolicy.Candidate c,SharedMovementCoordinator.Issue i){ticks++;tickHook.run();return progress;}
        public SharedMovementCoordinator.AppliedReceipt receipt(SharedMovementCoordinator.Lease l,SharedMovementCoordinator.Issue i){return receipt;}
        public boolean at(Vec3 g,double radius){return atGoal;}
        public void stopOwned(SharedMovementCoordinator.Lease l,SharedMovementCoordinator.Issue i){stops++;}
        void ack(){receipt=new SharedMovementCoordinator.AppliedReceipt(issue.token(),issue.receiptDomain(),31,time,GOAL,owner.player(),owner.world(),owner.connection());}
    }
    @Test void choosesAlternateAdmittedJourneyRatherThanCosmeticNoise(){var choices=List.of(c("left",SharedMovementPolicy.Mode.WALK,GOAL,12),c("right",SharedMovementPolicy.Mode.RUN,GOAL,13));var a=SharedMovementPolicy.select(choices,options(),2,null,0).orElseThrow();var b=SharedMovementPolicy.select(choices,options(),2,a.id(),1).orElseThrow();assertNotEquals(a.id(),b.id());}
    @Test void ignoresUnavailableAndExpensiveDevices(){var choices=List.of(c("walk",SharedMovementPolicy.Mode.WALK,GOAL,12),c("too-expensive",SharedMovementPolicy.Mode.AOTV,GOAL,30));assertEquals("walk",SharedMovementPolicy.select(choices,options(),2,null,0).orElseThrow().id());assertTrue(SharedMovementPolicy.select(List.of(choices.get(1)),options(),0,null,0).isEmpty());}
    @Test void duplicateIdsCannotGrantAmbiguousPermission(){assertTrue(SharedMovementPolicy.select(List.of(c("x",SharedMovementPolicy.Mode.WALK,GOAL,12),c("x",SharedMovementPolicy.Mode.RUN,GOAL,12)),options(),2,null,0).isEmpty());}
    @Test void rejectsUnknownGeometryAndDeviceTool(){assertThrows(IllegalArgumentException.class,()->new SharedMovementPolicy.Candidate("x",SharedMovementPolicy.Mode.AOTV,GOAL,2,1,new Object(),new Object(),null));assertThrows(IllegalArgumentException.class,()->new SharedMovementPolicy.Candidate("x",SharedMovementPolicy.Mode.JUMP,GOAL,2,0,null,new Object(),null));}
    @Test void cropWorkCannotRandomizeOrSpendTools(){assertThrows(IllegalArgumentException.class,()->new SharedMovementPolicy.Options(Set.of(SharedMovementPolicy.Mode.WALK,SharedMovementPolicy.Mode.AOTV),SharedMovementPolicy.Purpose.CROP_WORK,1,1000,.3,1.2));}
    @Test void noActionAfterContextRevocationDuringCandidateReads(){var p=new P();p.candidatesHook=()->p.valid=false;var s=new SharedMovementCoordinator(p);assertFalse(s.start(lease(),GOAL,options()));assertEquals(0,p.begins);assertTrue(p.stops>0);}
    @Test void dispatchContextLossRetiresIssuedGeneration(){var p=new P();p.beginHook=()->p.valid=false;var s=new SharedMovementCoordinator(p);assertFalse(s.start(lease(),GOAL,options()));assertEquals(1,p.begins);assertTrue(p.stops>0);}
    @Test void ordinaryArrivalRequiresActualOriginalPose(){var p=new P();var s=new SharedMovementCoordinator(p);assertTrue(s.start(lease(),GOAL,options()));p.progress=SharedMovementCoordinator.Progress.ARRIVED;assertEquals(SharedMovementCoordinator.State.MOVING,s.tick());p.atGoal=true;assertEquals(SharedMovementCoordinator.State.ARRIVED,s.tick());}
    @Test void transportWithoutNativeAckCannotCompleteOrRetry(){var p=new P();p.choices=List.of(c("aotv",SharedMovementPolicy.Mode.AOTV,GOAL,3));var s=new SharedMovementCoordinator(p);assertTrue(s.start(lease(),GOAL,options()));p.atGoal=true;p.progress=SharedMovementCoordinator.Progress.ARRIVED;for(int i=0;i<4;i++)assertEquals(SharedMovementCoordinator.State.WAITING_RECEIPT,s.tick());assertEquals(1,p.begins);p.time=1101;assertEquals(SharedMovementCoordinator.State.FAILED,s.tick());assertEquals(1,p.begins);}
    @Test void freshScopedAppliedAckCompletesTransport(){var p=new P();p.choices=List.of(c("aotv",SharedMovementPolicy.Mode.AOTV,GOAL,3));var s=new SharedMovementCoordinator(p);assertTrue(s.start(lease(),GOAL,options()));p.atGoal=true;p.ack();assertEquals(SharedMovementCoordinator.State.ARRIVED,s.tick());assertEquals(1,s.remainingToolUses());}
    @Test void staleAckAndForeignDomainsAreRejected(){for(boolean foreign:new boolean[]{false,true}){var p=new P();p.choices=List.of(c("aotv",SharedMovementPolicy.Mode.AOTV,GOAL,3));var s=new SharedMovementCoordinator(p);s.start(lease(),GOAL,options());p.receipt=new SharedMovementCoordinator.AppliedReceipt(p.issue.token(),foreign?new Object():p.issue.receiptDomain(),foreign?31:30,p.time,GOAL,p.owner.player(),p.owner.world(),p.owner.connection());assertEquals(SharedMovementCoordinator.State.FAILED,s.tick());assertEquals(1,p.begins);}}
    @Test void foreignPositionAndPwcCannotAcknowledgeTransport(){for(boolean foreign:new boolean[]{false,true}){var p=new P();p.choices=List.of(c("aotv",SharedMovementPolicy.Mode.AOTV,GOAL,3));var s=new SharedMovementCoordinator(p);s.start(lease(),GOAL,options());p.receipt=new SharedMovementCoordinator.AppliedReceipt(p.issue.token(),p.issue.receiptDomain(),31,p.time,foreign?GOAL:LANDING,foreign?new Object():p.owner.player(),p.owner.world(),p.owner.connection());assertEquals(SharedMovementCoordinator.State.FAILED,s.tick());}}
    @Test void lossDuringTickPreventsTerminalPublication(){var p=new P();var s=new SharedMovementCoordinator(p);s.start(lease(),GOAL,options());p.tickHook=()->p.valid=false;p.progress=SharedMovementCoordinator.Progress.ARRIVED;p.atGoal=true;assertEquals(SharedMovementCoordinator.State.FAILED,s.tick());}
    @Test void clockRollbackAndConfigurationRevocationReleaseOwnership(){for(boolean rollback:new boolean[]{false,true}){var p=new P();var s=new SharedMovementCoordinator(p);s.start(lease(),GOAL,options());if(rollback)p.time=99;else p.valid=false;assertEquals(SharedMovementCoordinator.State.FAILED,s.tick());assertEquals(0,p.ticks);assertTrue(p.stops>0);}}
    @Test void leaseIdentityIncludesStoreAndCameraGeneration(){var l=lease();assertTrue(l.same(l));assertFalse(l.same(new SharedMovementCoordinator.Lease(l.module(),l.player(),l.world(),l.connection(),l.inputOwner(),l.cameraOwner(),new Object(),l.configRevision(),l.cameraEpoch())));assertFalse(l.same(new SharedMovementCoordinator.Lease(l.module(),l.player(),l.world(),l.connection(),l.inputOwner(),l.cameraOwner(),l.configStore(),l.configRevision(),l.cameraEpoch()+1)));}
    @Test void cancellationIsTerminalAndNeverTicksOldIssue(){var p=new P();var s=new SharedMovementCoordinator(p);s.start(lease(),GOAL,options());s.stop();assertEquals(SharedMovementCoordinator.State.STOPPED,s.tick());assertEquals(0,p.ticks);}
    @Test void dormantDeviceAimDoesNotSpendOrAcceptArrival(){var p=new P(){@Override public SharedMovementCoordinator.Issue begin(SharedMovementCoordinator.Lease l,SharedMovementPolicy.Candidate c){begins++;issue=new SharedMovementCoordinator.Issue(new Object(),new Object(),30,time,false);return issue;}};p.choices=List.of(c("aotv",SharedMovementPolicy.Mode.AOTV,GOAL,3));var s=new SharedMovementCoordinator(p);assertTrue(s.start(lease(),GOAL,options()));assertEquals(2,s.remainingToolUses());assertEquals(SharedMovementCoordinator.State.MOVING,s.tick());p.atGoal=true;p.progress=SharedMovementCoordinator.Progress.ARRIVED;assertEquals(SharedMovementCoordinator.State.FAILED,s.tick());assertEquals(2,s.remainingToolUses());}
    @Test void laterActualUseSuppliesRealBaselineBeforeAck(){var p=new P(){SharedMovementCoordinator.Issue dispatched;@Override public SharedMovementCoordinator.Issue begin(SharedMovementCoordinator.Lease l,SharedMovementPolicy.Candidate c){begins++;issue=new SharedMovementCoordinator.Issue(new Object(),new Object(),0,time,false);return issue;}@Override public SharedMovementCoordinator.Issue dispatchedIssue(SharedMovementCoordinator.Lease l,SharedMovementCoordinator.Issue armed){dispatched=new SharedMovementCoordinator.Issue(new Object(),new Object(),74,time,true);receipt=new SharedMovementCoordinator.AppliedReceipt(dispatched.token(),dispatched.receiptDomain(),75,time,GOAL,l.player(),l.world(),l.connection());return dispatched;}};p.choices=List.of(c("aotv",SharedMovementPolicy.Mode.AOTV,GOAL,3));var s=new SharedMovementCoordinator(p);assertTrue(s.start(lease(),GOAL,options()));p.time=110;p.atGoal=true;assertEquals(SharedMovementCoordinator.State.ARRIVED,s.tick());assertEquals(1,s.remainingToolUses());}
    @Test void dispatchExceptionRetiresKeysAndPreservesOriginalFailure(){var thrown=new IllegalStateException("native begin");var p=new P(){@Override public SharedMovementCoordinator.Issue begin(SharedMovementCoordinator.Lease l,SharedMovementPolicy.Candidate c){throw thrown;}};var s=new SharedMovementCoordinator(p);assertSame(thrown,assertThrows(IllegalStateException.class,()->s.start(lease(),GOAL,options())));assertTrue(p.stops>0);assertEquals(SharedMovementCoordinator.State.FAILED,s.state());}
    @Test void tickExceptionRetiresOwnedIssueBeforeRethrowing(){var thrown=new AssertionError("native tick");var p=new P(){@Override public SharedMovementCoordinator.Progress tick(SharedMovementCoordinator.Lease l,SharedMovementPolicy.Candidate c,SharedMovementCoordinator.Issue i){throw thrown;}};var s=new SharedMovementCoordinator(p);s.start(lease(),GOAL,options());assertSame(thrown,assertThrows(AssertionError.class,s::tick));assertTrue(p.stops>0);assertEquals(SharedMovementCoordinator.State.FAILED,s.state());}
    @Test void reservedGroundTransitNeverGrantsDeviceSubstitution(){assertThrows(IllegalArgumentException.class,()->new SharedMovementPolicy.Options(Set.of(SharedMovementPolicy.Mode.WALK,SharedMovementPolicy.Mode.AOTV),SharedMovementPolicy.Purpose.GENERAL_GROUND_TRAVEL,1,1000,.3,1.2));var allowed=new SharedMovementPolicy.Options(Set.of(SharedMovementPolicy.Mode.WALK,SharedMovementPolicy.Mode.RUN,SharedMovementPolicy.Mode.JUMP),SharedMovementPolicy.Purpose.GENERAL_GROUND_TRAVEL,0,1000,.3,1.2);assertTrue(SharedMovementPolicy.select(List.of(c("aotv",SharedMovementPolicy.Mode.AOTV,GOAL,3)),allowed,1,null,0).isEmpty());}
    @Test void twoNativeUsesRequireTheirOwnFreshIssueAndAckThenGroundSuffix(){
        var first=new Vec3(8,70,0);var second=new Vec3(16,70,0);var finish=new Vec3(24,70,0);
        var p=new P(){int starts;Vec3 observed=new Vec3(0,70,0);
            @Override public List<SharedMovementPolicy.Candidate> candidates(Vec3 g,SharedMovementPolicy.Options o,int uses){return List.of(starts==0?c("first",SharedMovementPolicy.Mode.AOTV,first,20):starts==1?c("second",SharedMovementPolicy.Mode.AOTV,second,12):c("suffix",SharedMovementPolicy.Mode.WALK,finish,8));}
            @Override public SharedMovementCoordinator.Issue begin(SharedMovementCoordinator.Lease l,SharedMovementPolicy.Candidate c){starts++;issue=new SharedMovementCoordinator.Issue(new Object(),new Object(),30+starts,time,SharedMovementPolicy.device(c.mode()));return issue;}
            @Override public boolean at(Vec3 g,double radius){return observed.distanceTo(g)<=radius;}
        };
        var s=new SharedMovementCoordinator(p);assertTrue(s.start(lease(),finish,options()));var a=p.issue;p.observed=first;
        p.receipt=new SharedMovementCoordinator.AppliedReceipt(a.token(),a.receiptDomain(),a.baseline()+1,p.time,first,p.owner.player(),p.owner.world(),p.owner.connection());
        assertEquals(SharedMovementCoordinator.State.WAITING_RECEIPT,s.tick());var b=p.issue;assertNotSame(a.token(),b.token());assertTrue(b.baseline()>a.baseline());
        p.observed=second;p.time++;
        p.receipt=new SharedMovementCoordinator.AppliedReceipt(b.token(),b.receiptDomain(),b.baseline()+1,p.time,second,p.owner.player(),p.owner.world(),p.owner.connection());
        assertEquals(SharedMovementCoordinator.State.MOVING,s.tick());assertEquals(0,s.remainingToolUses());p.observed=finish;p.progress=SharedMovementCoordinator.Progress.ARRIVED;
        assertEquals(SharedMovementCoordinator.State.ARRIVED,s.tick());assertEquals(3,p.starts);
    }
    @Test void originalGroundCubeRejectsFortyEightAndFortyButAdmitsThirtyTwo(){var origin=new Vec3(112.5,76,67.5);assertFalse(SharedMovementPolicy.withinGroundHorizon(origin,new Vec3(160.5,76,67.5),32));assertFalse(SharedMovementPolicy.withinGroundHorizon(new Vec3(120.5,76,67.5),new Vec3(160.5,76,67.5),32));assertTrue(SharedMovementPolicy.withinGroundHorizon(new Vec3(128.5,76,67.5),new Vec3(160.5,76,67.5),32));assertFalse(SharedMovementPolicy.withinGroundHorizon(origin,new Vec3(1e200,76,67.5),32));}
}
